// Fetch suppliers from API
function fetchSuppliers() {
    fetch('../../../../server/api/vouchers/payment_voucher/get-suppliers.php')
        .then(response => response.json())
        .then(data => {
            if (data.success) {
                suppliers = data.data.map(supplier => ({
                    code: supplier.supplier_code,
                    name: supplier.supplier_name
                }));
                bulkSuppliers = suppliers;
                setupSearchableDropdown('supplierCode', 'supplierDropdown', suppliers, 'name', 'code');
                checkBulkDataReady();
            }
        })
        .catch(error => console.error('Error fetching suppliers:', error));
}

// Fetch customers from API
function fetchCustomers() {
    fetch('../../../../server/api/vouchers/payment_voucher/get-customers.php')
        .then(response => response.json())
        .then(data => {
            if (data.success) {
                customers = data.data.map(customer => ({
                    code: customer.customer_code,
                    name: customer.customer_name
                }));
                setupSearchableDropdown('supplierCode', 'supplierDropdown', customers, 'name', 'code');
            }
        })
        .catch(error => console.error('Error fetching customers:', error));
}

